     1→import { useCallback, useEffect, useRef, useState } from "react";
     2→import type { StepStatus, StreamWarning } from "../types";
     3→import { API_BASE_URL } from "../config";
     4→
     5→interface UseChatStreamOptions {
     6→  sessionId?: string | null;
     7→  onComplete?: () => Promise<void> | void;
     8→}
     9→
    10→interface StreamingTurn {
    11→  user: string;
    12→  assistant: string;
    13→}
    14→
    15→interface UseChatStreamResult {
    16→  sendMessage: (message: string) => Promise<void>;
    17→  isStreaming: boolean;
    18→  streamingTurn: StreamingTurn | null;
    19→  stepStatuses: StepStatus[];
    20→  warning: StreamWarning | null;
    21→  error: string | null;
    22→}
    23→
    24→export function useChatStream(
    25→  options: UseChatStreamOptions
    26→): UseChatStreamResult {
    27→  const { sessionId, onComplete } = options;
    28→  const [isStreaming, setIsStreaming] = useState(false);
    29→  const [streamingTurn, setStreamingTurn] = useState<StreamingTurn | null>(null);
    30→  const [stepMap, setStepMap] = useState<Record<string, StepStatus>>({});
    31→  const [warning, setWarning] = useState<StreamWarning | null>(null);
    32→  const [error, setError] = useState<string | null>(null);
    33→  const abortRef = useRef<AbortController | null>(null);
    34→
    35→  useEffect(() => {
    36→    return () => {
    37→      abortRef.current?.abort();
    38→    };
    39→  }, []);
    40→
    41→  const handleBlock = useCallback(
    42→    (block: string) => {
    43→    let event: string | null = null;
    44→    let dataStr = "";
    45→    for (const line of block.split("\n")) {
    46→      if (line.startsWith("event:")) {
    47→        event = line.replace("event:", "").trim();
    48→      } else if (line.startsWith("data:")) {
    49→        dataStr += line.replace("data:", "").trim();
    50→      }
    51→    }
    52→
    53→    if (!event) {
    54→      console.log("[handleBlock] No event found in block");
    55→      return;
    56→    }
    57→
    58→    let data: any = {};
    59→    if (dataStr) {
    60→      try {
    61→        data = JSON.parse(dataStr);
    62→      } catch {
    63→        data = { message: dataStr };
    64→      }
    65→    }
    66→
    67→    console.log("[handleBlock] Event:", event, "Data:", data);
    68→
    69→    switch (event) {
    70→      case "step":
    71→        if (data.id) {
    72→          setStepMap((prev) => ({
    73→            ...prev,
    74→            [data.id]: { id: data.id, status: data.status ?? "complete", ...data }
    75→          }));
    76→        }
    77→        break;
    78→      case "chunk":
    79→        console.log("[handleBlock] Chunk content:", data.content);
    80→        if (typeof data.content === "string") {
    81→          setStreamingTurn((prev) =>
    82→            prev ? { ...prev, assistant: prev.assistant + data.content } : prev
    83→          );
    84→        }
    85→        break;
    86→      case "warning":
    87→        setWarning({ code: data.code, message: data.message ?? "Warning" });
    88→        break;
    89→      case "error":
    90→        setError(data.message ?? "Pipeline error");
    91→        break;
    92→      case "done":
    93→        setStepMap({});
    94→        if (onComplete) {
    95→          // Wait 500ms for backend to save the turn before refreshing
    96→          // Keep streaming turn visible until history is fetched
    97→          setTimeout(() => {
    98→            Promise.resolve(onComplete())
    99→              .then(() => setStreamingTurn(null))
   100→              .catch((err) => {
   101→                console.error("Refresh failed", err);
   102→                setStreamingTurn(null);
   103→              });
   104→          }, 500);
   105→        } else {
   106→          setStreamingTurn(null);
   107→        }
   108→        break;
   109→      default:
   110→        break;
   111→    }
   112→  },
   113→  [onComplete]
   114→  );
   115→
   116→  const sendMessage = useCallback(
   117→    async (message: string) => {
   118→      if (!sessionId) {
   119→        setError("Session not ready yet.");
   120→        return;
   121→      }
   122→
   123→      const trimmed = message.trim();
   124→      if (!trimmed) {
   125→        return;
   126→      }
   127→
   128→      abortRef.current?.abort();
   129→      const controller = new AbortController();
   130→      abortRef.current = controller;
   131→
   132→      setIsStreaming(true);
   133→      setStreamingTurn({ user: trimmed, assistant: "" });
   134→      setStepMap({});
   135→      setWarning(null);
   136→      setError(null);
