docker exec turnstile-sak-router python3 << 'EOF'
import json
import os
import httpx

models = ["gpt-5.2", "gpt-5.2-pro", "gpt-5.1", "gpt-5.1-codex", "gpt-5-mini", "gpt-5-nano"]
api_key = os.environ.get("OPENAI_API_KEY")

results = {}

for model in models:
    # Test with max_completion_tokens to see what errors we get
    test_values = [128000, 64000, 32000, 16000, 8000, 4000]

    for max_tokens in test_values:
        try:
            with httpx.Client(timeout=10.0) as client:
                response = client.post(
                    "https://api.openai.com/v1/chat/completions",
                    headers={
                        "Authorization": f"Bearer {api_key}",
                        "Content-Type": "application/json",
                    },
                    json={
                        "model": model,
                        "messages": [{"role": "user", "content": "Hi"}],
                        "max_completion_tokens": max_tokens,
                        "max_tokens": 1,  # Minimal output to speed up test
                    },
                )

                if response.status_code == 200:
                    results[model] = max_tokens
                    print(f"{model}: max_completion_tokens={max_tokens} ✓")
                    break
                elif response.status_code == 400:
                    error_data = response.json()
                    error_msg = error_data.get("error", {}).get("message", "")
                    if "max_completion_tokens" in error_msg.lower():
                        print(f"{model}: max_completion_tokens={max_tokens} ✗ (trying lower)")
                        continue
                    else:
                        # Different error, skip this model
                        print(f"{model}: Error - {error_msg}")
                        break

        except Exception as e:
            print(f"{model}: Exception - {e}")
            break

    if model not in results:
        results[model] = None

print("\n=== RESULTS ===")
print(json.dumps(results, indent=2))
EOF

