async function proxySse(
  req: Request,
  res: Response,
  targetUrl: string,
  body: string,
  extraHeaders?: Record<string, string>
) {
  const controller = new AbortController();

  // Only abort if client closes AFTER we've started streaming
  let streamStarted = false;
  req.on("close", () => {
    if (streamStarted) {
      controller.abort();
    }
  });

  try {
    const upstream = await fetch(targetUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...extraHeaders
      },
      body,
      signal: controller.signal
    });

    if (!upstream.ok) {
      const errorPayload = await upstream.text();
      res.status(upstream.status);
      res.type(upstream.headers.get("content-type") ?? "application/json");
      res.send(errorPayload || JSON.stringify({ error: { message: "Upstream error" } }));
      return;
    }

    res.status(200);
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    streamStarted = true;

    const reader = upstream.body?.getReader();

    if (!reader) {
      res.write(`event: error\ndata: ${JSON.stringify({
        code: "stream_unavailable",
        message: "No upstream stream"
      })}\n\n`);
      res.end();
      return;
    }

    const close = () => reader.cancel().catch(() => undefined);
    req.on("close", close);

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        break;
      }
      if (value) {
        res.write(Buffer.from(value));
      }
    }
    res.end();
  } catch (err) {
    if (controller.signal.aborted && streamStarted) {
      // Client disconnected during stream - this is normal
      return;
    }
    // Other errors - send error response if we haven't started streaming yet
    if (!streamStarted && !res.headersSent) {
      res.status(500).json({
        error: {
          code: "proxy_error",
          message: err instanceof Error ? err.message : "SSE proxy error"
        }
      });
    }
  }
}

