import { useState } from "react";
import type { Turn } from "../types";

interface TurnCardProps {
  turn: Turn;
  active?: boolean;
}

export function TurnCard({ turn, active = false }: TurnCardProps) {
  const [showTokens, setShowTokens] = useState(false);
  const breakdown = turn.metadata?.token_breakdown;

  return (
    <div
      className={`turn-card ${active ? "turn-card--active" : ""}`}
      role="group"
      aria-labelledby={`${turn.id}-label`}
    >
      <div className="turn-card__meta">
        <span id={`${turn.id}-label`}>Turn {turn.id}</span>
        <time dateTime={turn.timestamp}>
          {new Date(turn.timestamp).toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit"
          })}
        </time>
        {breakdown?.total && (
          <button
            className="token-toggle"
            onClick={() => setShowTokens(!showTokens)}
            aria-expanded={showTokens}
          >
            {breakdown.total.toLocaleString()} tokens
          </button>
        )}
      </div>
      {showTokens && breakdown && (
        <div className="token-breakdown">
          {breakdown.docs && <div className="token-row"><span>Docs:</span><span>{breakdown.docs.toLocaleString()}</span></div>}
          {breakdown.persona && <div className="token-row"><span>Persona:</span><span>{breakdown.persona.toLocaleString()}</span></div>}
          {breakdown.session && <div className="token-row"><span>Session:</span><span>{breakdown.session.toLocaleString()}</span></div>}
          {breakdown.llm && <div className="token-row"><span>LLM:</span><span>{breakdown.llm.toLocaleString()}</span></div>}
        </div>
      )}
      <div className="turn-card__message">
        <p className="turn-card__user">{turn.user}</p>
        <p className="turn-card__assistant">{turn.assistant || "…"}</p>
      </div>
    </div>
  );
}

